// src/lib/poppinsContractFonts.ts
//
// Poppins (identidade visual da CBC) — subsets Latin (pt-BR completo) embutidos em base64
// para o jsPDF: Regular, Italic, Medium e Bold. Registrada como família "PoppinsCBC".
// Gerado a partir dos TTF oficiais da Google Fonts (licença OFL) com pyftsubset.

const POPPINS_REGULAR = "";
const POPPINS_ITALIC = "";
const POPPINS_MEDIUM = "";
const POPPINS_BOLD = "";

export const POPPINS_FAMILY = 'PoppinsCBC';

/** Registra as 4 variações no documento. Retorna false (e o chamador cai em Helvetica) se algo falhar. */
export function registerPoppinsFamily(doc: any): boolean {
  try {
    const files: [string, string, string][] = [
      ['PoppinsCBC-Regular.ttf', POPPINS_REGULAR, 'normal'],
      ['PoppinsCBC-Italic.ttf', POPPINS_ITALIC, 'italic'],
      ['PoppinsCBC-Medium.ttf', POPPINS_MEDIUM, 'medium'],
      ['PoppinsCBC-Bold.ttf', POPPINS_BOLD, 'bold'],
    ];
    for (const [file, data, style] of files) {
      doc.addFileToVFS(file, data);
      doc.addFont(file, POPPINS_FAMILY, style);
    }
    return true;
  } catch {
    return false;
  }
}
